var e=JSON.parse(`[{"id":"des-creme-caramel","name":"Crème caramel au lait entier","description":"La crème renversée de toujours : un flan vanillé, lisse et tremblotant, nappé d'un caramel ambré qui coule en sauce au démoulage.","emoji":"🍮","category":"dessert","mealTypes":["dessert"],"cuisine":"francaise","prepTime":20,"cookTime":30,"restTime":240,"difficulty":"facile","servings":6,"ingredients":[{"id":"lait","qty":750,"unit":"ml","note":"entier, idéalement cru"},{"id":"oeuf","qty":5,"unit":"piece"},{"id":"sucre","qty":150,"unit":"g","note":"90 g pour la crème, 60 g pour le caramel"},{"id":"eau","qty":30,"unit":"ml","note":"pour le caramel"},{"id":"vanille","qty":1,"unit":"cac","note":"1 gousse fendue ou 1 c. à café d'extrait"}],"steps":["Faites chauffer le lait avec la gousse de vanille fendue et grattée jusqu'aux premiers frémissements, puis coupez le feu et laissez infuser 10 min.","Caramel : dans une petite casserole, chauffez 60 g de sucre et l'eau à feu moyen sans remuer, 6 à 8 min, jusqu'à une couleur ambre foncé. Versez aussitôt dans 6 ramequins (ou un moule de 18 cm) et inclinez pour napper le fond.","Fouettez les œufs et 90 g de sucre juste pour mélanger, sans faire mousser. Versez le lait chaud en filet en remuant, puis filtrez au chinois.","Versez la crème sur le caramel durci et couvrez chaque ramequin d'une feuille d'aluminium.","Cuisson douce à la vapeur : posez les ramequins dans une grande cocotte ou un panier vapeur, sur un linge plié, avec 3 cm d'eau frémissante. Couvrez, coincez un torchon sous le couvercle et cuisez 20 à 25 min à feu très doux (l'eau doit à peine frémir) : la crème tremble encore légèrement au centre et une lame ressort propre.","Laissez refroidir à température ambiante puis réfrigérez au moins 4 h. Pour démouler, passez une lame fine sur le pourtour et retournez d'un coup sur une assiette creuse."],"tags":["préparation à l’avance","familial","économique","sans gluten"],"seasons":[],"technique":"vapeur","flavors":["cremeux","reconfortant"],"tips":"Se garde 3 jours au frais. Au four, comptez 30 min au bain-marie à 150 °C : au-delà, la crème bulle et devient granuleuse."},{"id":"des-flan-patissier-sans-pate","name":"Flan pâtissier sans pâte","description":"Un flan parisien épais et onctueux, cuit sans fond de pâte : crème vanillée prise à la maïzena, surface dorée et tachetée.","emoji":"🥧","category":"dessert","mealTypes":["dessert"],"cuisine":"francaise","prepTime":15,"cookTime":50,"restTime":300,"difficulty":"facile","servings":8,"ingredients":[{"id":"lait","qty":800,"unit":"ml","note":"entier"},{"id":"creme-liquide","qty":200,"unit":"ml"},{"id":"oeuf","qty":2,"unit":"piece"},{"id":"jaune-oeuf","qty":2,"unit":"piece"},{"id":"sucre","qty":140,"unit":"g"},{"id":"fecule-mais","qty":90,"unit":"g"},{"id":"beurre","qty":20,"unit":"g","note":"pour le moule"},{"id":"vanille","qty":1,"unit":"cac","note":"1 gousse ou 1 c. à café d'extrait"}],"steps":["Préchauffez le four à 180 °C. Beurrez généreusement un moule à manqué de 22 cm à bords hauts.","Portez à frémissement 600 ml de lait avec la crème et la vanille grattée, à feu moyen.","Dans un saladier, fouettez les œufs et les jaunes avec le sucre, la maïzena et les 200 ml de lait restants froids jusqu'à un mélange lisse, sans grumeaux.","Versez le lait chaud sur ce mélange en fouettant, reversez le tout dans la casserole et faites épaissir à feu moyen sans cesser de fouetter, 2 à 3 min après les premiers bouillons : la crème doit napper épaissement et faire des bulles lentes.","Versez dans le moule, lissez et enfournez 45 à 50 min, jusqu'à ce que la surface soit bien dorée avec des taches brunes.","Laissez refroidir 1 h à température ambiante puis 4 h au réfrigérateur avant de démouler et de couper en parts nettes."],"tags":["four","préparation à l’avance","familial","économique","sans gluten"],"seasons":[],"technique":"four","flavors":["cremeux","lacte","reconfortant"],"tips":"Meilleur le lendemain, bien froid. Se garde 3 jours au frais, filmé au contact."},{"id":"des-iles-flottantes","name":"Îles flottantes à la vanille","description":"Des nuages de blancs en neige pochés dans le lait, posés sur une crème anglaise vanillée bien froide et filés de caramel.","emoji":"☁️","category":"dessert","mealTypes":["dessert"],"cuisine":"francaise","prepTime":25,"cookTime":20,"restTime":120,"difficulty":"facile","servings":4,"ingredients":[{"id":"lait","qty":600,"unit":"ml","note":"entier"},{"id":"jaune-oeuf","qty":4,"unit":"piece"},{"id":"blanc-oeuf","qty":4,"unit":"piece"},{"id":"sucre","qty":100,"unit":"g","note":"50 g crème, 20 g meringue, 30 g caramel"},{"id":"vanille","qty":1,"unit":"cac","note":"1 gousse fendue"},{"id":"amande","qty":20,"unit":"g","note":"effilées, grillées","optional":true},{"id":"sel","qty":1,"unit":"pincee"}],"steps":["Faites frémir le lait avec la vanille fendue et grattée dans une large casserole, à feu moyen.","Montez les blancs avec la pincée de sel en neige ferme, puis ajoutez 20 g de sucre et fouettez encore 1 min jusqu'à un aspect brillant.","Baissez le feu pour que le lait frémisse à peine. Déposez-y des grosses quenelles de blancs (2 cuillères à soupe) et pochez 1 min par face : elles gonflent et se raffermissent. Égouttez sur une grille. Gardez le lait.","Crème anglaise : fouettez les jaunes avec 50 g de sucre jusqu'à blanchiment, versez le lait de pochage filtré dessus, reversez en casserole et cuisez à feu doux en remuant en huit à la spatule, 6 à 8 min, sans bouillir, jusqu'à ce que la crème nappe la spatule (le doigt y trace un sillon net, 82 °C).","Filtrez la crème dans un saladier froid et refroidissez-la, puis réfrigérez au moins 2 h.","Au moment de servir, faites un caramel avec 30 g de sucre et 1 c. à soupe d'eau, à feu moyen jusqu'à ambre. Versez la crème dans des coupes, posez les îles et filez le caramel dessus à la cuillère, avec les amandes grillées."],"tags":["préparation à l’avance","familial","économique","sans gluten"],"seasons":[],"technique":"poche","flavors":["lacte","sucre","frais"],"tips":"La crème anglaise se garde 2 jours ; pochez les blancs le jour même."},{"id":"des-riz-au-lait-caramel-beurre-sale","name":"Riz au lait, caramel au beurre salé","description":"Riz rond cuit lentement dans le lait entier jusqu'à devenir crémeux, servi tiède ou froid sous un caramel au beurre demi-sel.","emoji":"🍚","category":"dessert","mealTypes":["dessert"],"cuisine":"francaise","prepTime":10,"cookTime":45,"difficulty":"tres-facile","servings":6,"ingredients":[{"id":"riz-rond","qty":150,"unit":"g"},{"id":"lait","qty":1000,"unit":"ml","note":"entier"},{"id":"sucre","qty":110,"unit":"g","note":"40 g pour le riz, 70 g pour le caramel"},{"id":"beurre","qty":30,"unit":"g","note":"demi-sel"},{"id":"creme-liquide","qty":100,"unit":"ml","note":"pour le caramel"},{"id":"vanille","qty":1,"unit":"cac","note":"1 gousse fendue"},{"id":"sel","qty":1,"unit":"pincee","note":"fleur de sel"}],"steps":["Rincez le riz, puis blanchissez-le 2 min dans de l'eau bouillante et égouttez : il libérera moins d'amidon collant.","Portez le lait à frémissement avec la vanille fendue. Ajoutez le riz, baissez à feu très doux (petits frémissements) et cuisez 40 à 45 min en remuant toutes les 5 min, jusqu'à ce que les grains soient fondants et le lait épaissi en crème.","Hors du feu, incorporez 40 g de sucre. Le riz paraît encore un peu liquide : il épaissit en refroidissant. Répartissez en verrines.","Caramel : faites fondre 70 g de sucre à sec à feu moyen, sans remuer, jusqu'à ambre foncé (5 min). Hors du feu, ajoutez le beurre en morceaux, puis la crème chaude en filet (attention aux projections), et remettez 1 min sur feu doux en fouettant.","Ajoutez la fleur de sel et nappez le riz d'une cuillère de caramel. Servez tiède ou après 2 h au frais."],"tags":["réconfortant","familial","économique","préparation à l’avance","sans gluten"],"seasons":["automne","hiver"],"technique":"mijote","flavors":["cremeux","reconfortant","lacte"],"tips":"Le caramel se conserve 1 semaine au frais en pot ; réchauffez-le 10 s au micro-ondes."},{"id":"des-arroz-con-leche","name":"Arroz con leche au citron et à la cannelle","description":"Le riz au lait espagnol parfumé au zeste de citron et à la cannelle, très crémeux, servi froid saupoudré de cannelle.","emoji":"🍋","category":"dessert","mealTypes":["dessert"],"cuisine":"espagnole","prepTime":10,"cookTime":50,"restTime":120,"difficulty":"tres-facile","servings":6,"ingredients":[{"id":"riz-rond","qty":160,"unit":"g"},{"id":"lait","qty":1100,"unit":"ml","note":"entier"},{"id":"sucre","qty":90,"unit":"g"},{"id":"citron","qty":1,"unit":"piece","note":"zeste en larges rubans"},{"id":"orange","qty":0.5,"unit":"piece","note":"zeste en ruban","optional":true},{"id":"cannelle","qty":1,"unit":"cac","note":"1 bâton + poudre pour servir"},{"id":"beurre","qty":15,"unit":"g"}],"steps":["Prélevez le zeste du citron en larges rubans avec un économe, sans la peau blanche amère.","Dans une casserole à fond épais, mettez le riz, le beurre, le bâton de cannelle et les zestes avec 200 ml d'eau ; faites frémir 5 min jusqu'à absorption de l'eau.","Ajoutez le lait, portez à frémissement puis baissez à feu doux. Cuisez 40 à 45 min en remuant souvent (le fond accroche facilement), jusqu'à une texture de crème coulante.","Ajoutez le sucre et poursuivez 5 min. Retirez cannelle et zestes.","Versez dans des bols, laissez refroidir puis réfrigérez 2 h. Saupoudrez de cannelle moulue juste avant de servir."],"tags":["économique","familial","préparation à l’avance","sans gluten"],"seasons":[],"technique":"mijote","flavors":["cremeux","acidule","lacte"],"tips":"En Asturies, on caramélise le dessus au fer ou au chalumeau avec une fine couche de sucre."},{"id":"des-kheer-cardamome-pistache","name":"Kheer à la cardamome, safran et pistaches","description":"Riz au lait indien longuement réduit, parfumé à la cardamome et au safran, enrichi de ghee, raisins secs et pistaches.","emoji":"🥛","category":"dessert","mealTypes":["dessert"],"cuisine":"indienne","prepTime":10,"cookTime":55,"difficulty":"facile","servings":4,"ingredients":[{"id":"riz-blanc","qty":60,"unit":"g","note":"basmati"},{"id":"lait","qty":1000,"unit":"ml","note":"entier"},{"id":"sucre","qty":60,"unit":"g"},{"id":"beurre-clarifie","qty":10,"unit":"g","note":"ghee"},{"id":"cardamome","qty":0.5,"unit":"cac","note":"graines de 6 gousses écrasées"},{"id":"safran","qty":1,"unit":"pincee"},{"id":"pistache","qty":30,"unit":"g","note":"concassées"},{"id":"amande","qty":30,"unit":"g","note":"effilées"},{"id":"raisins-secs","qty":30,"unit":"g"}],"steps":["Rincez le riz et laissez-le tremper 20 min dans l'eau froide, puis égouttez et concassez-le grossièrement entre les doigts.","Faites chauffer le ghee dans une casserole à fond épais, ajoutez le riz et nacrez-le 2 min à feu moyen.","Versez le lait, portez à ébullition en remuant, puis baissez à feu doux. Laissez réduire 45 à 50 min en grattant le fond et les bords toutes les 5 min : le lait doit réduire d'environ un tiers et le riz se défaire.","Infusez le safran dans 1 c. à soupe de lait chaud. Ajoutez au kheer le sucre, la cardamome, le safran, les raisins secs et la moitié des fruits secs ; cuisez encore 5 min.","Servez tiède ou froid (il épaissit beaucoup au frais), parsemé du reste des pistaches et amandes."],"tags":["réconfortant","préparation à l’avance","sans gluten","familial"],"seasons":["automne","hiver"],"technique":"mijote","flavors":["epice","cremeux","lacte"],"tips":"Se garde 3 jours au réfrigérateur ; détendez-le avec un peu de lait froid s'il a trop épaissi."},{"id":"des-sutlac-four","name":"Sütlaç, riz au lait turc gratiné au four","description":"Le riz au lait d'Istanbul, lié à la farine de riz puis passé sous le gril dans des ramequins jusqu'à une peau caramélisée.","emoji":"🍮","category":"dessert","mealTypes":["dessert"],"cuisine":"turque","prepTime":15,"cookTime":45,"restTime":180,"difficulty":"facile","servings":6,"ingredients":[{"id":"riz-rond","qty":100,"unit":"g"},{"id":"eau","qty":300,"unit":"ml"},{"id":"lait","qty":1000,"unit":"ml","note":"entier"},{"id":"farine-riz","qty":40,"unit":"g","note":"farine de riz fine"},{"id":"sucre","qty":120,"unit":"g"},{"id":"vanille","qty":1,"unit":"cac","note":"extrait","optional":true},{"id":"cannelle","qty":1,"unit":"cac","note":"pour servir","optional":true},{"id":"noisette","qty":30,"unit":"g","note":"torréfiées et moulues","optional":true}],"steps":["Cuisez le riz rincé dans l'eau à feu moyen, 12 à 15 min, jusqu'à absorption presque totale.","Ajoutez 850 ml de lait, portez à frémissement et cuisez 15 min à feu doux en remuant.","Délayez la farine de riz dans les 150 ml de lait restants froids, versez dans la casserole avec le sucre et la vanille et cuisez encore 5 min en remuant sans cesse : le mélange doit napper épais la cuillère.","Répartissez dans 6 ramequins en terre ou en verre allant au four, posés dans un plat rempli de 2 cm d'eau froide.","Passez sous le gril du four le plus près possible de la résistance, 10 à 12 min, jusqu'à ce que la surface soit tachetée de brun foncé.","Laissez refroidir puis réfrigérez au moins 3 h. Servez froid, saupoudré de cannelle ou de noisettes moulues."],"tags":["four","préparation à l’avance","économique","sans gluten"],"seasons":[],"technique":"four","flavors":["lacte","cremeux","grille"],"tips":"Le bain d'eau froide empêche le fond de bouillir pendant que le dessus caramélise."},{"id":"des-panna-cotta-kefir-miel","name":"Panna cotta au kéfir et au miel, grenade","description":"Une panna cotta plus vive et digeste : moitié crème, moitié kéfir de lait, sucrée au miel, couronnée de grains de grenade et de pistaches.","emoji":"🍶","category":"dessert","mealTypes":["dessert"],"cuisine":"italienne","prepTime":15,"cookTime":5,"restTime":240,"difficulty":"tres-facile","servings":6,"ingredients":[{"id":"creme-liquide","qty":300,"unit":"ml","note":"entière"},{"id":"kefir","qty":400,"unit":"ml","note":"bien froid"},{"id":"miel","qty":90,"unit":"g","note":"doux (acacia)"},{"id":"gelatine","qty":4,"unit":"piece","note":"feuilles de 2 g"},{"id":"vanille","qty":1,"unit":"cac","note":"1 gousse ou extrait"},{"id":"grenade","qty":1,"unit":"piece","note":"égrenée"},{"id":"pistache","qty":20,"unit":"g","note":"concassées","optional":true}],"steps":["Faites tremper les feuilles de gélatine 10 min dans un bol d'eau froide.","Chauffez la crème avec le miel et la vanille grattée à feu moyen jusqu'aux premiers frémissements (ne la faites pas bouillir).","Hors du feu, ajoutez la gélatine bien essorée et fouettez 30 s pour la dissoudre complètement. Laissez tiédir 10 min (le mélange doit être tiède au doigt, environ 40 °C).","Incorporez le kéfir froid en fouettant doucement : le kéfir n'est pas chauffé, ses ferments restent vivants.","Répartissez dans 6 verrines et réfrigérez au moins 4 h, jusqu'à ce que la panna cotta tremble sans couler quand on incline le verre.","Au moment de servir, parsemez de grains de grenade et de pistaches, et d'un filet de miel si vous le souhaitez."],"tags":["préparation à l’avance","fermenté","léger","sans gluten"],"seasons":["automne","hiver"],"technique":"sans-cuisson","flavors":["acidule","cremeux","fruite"],"tips":"Au printemps et en été, remplacez la grenade par des fraises ou des abricots rôtis. Se garde 3 jours."},{"id":"des-mahalabia-fleur-oranger","name":"Mahalabia à la fleur d'oranger et aux pistaches","description":"Crème de lait levantine soyeuse, prise à l'amidon, parfumée à la fleur d'oranger et au zeste d'orange, couverte de pistaches.","emoji":"🌸","category":"dessert","mealTypes":["dessert"],"cuisine":"levantine","prepTime":10,"cookTime":10,"restTime":180,"difficulty":"tres-facile","servings":6,"ingredients":[{"id":"lait","qty":900,"unit":"ml","note":"entier"},{"id":"creme-liquide","qty":100,"unit":"ml"},{"id":"fecule-mais","qty":60,"unit":"g"},{"id":"sucre","qty":90,"unit":"g"},{"id":"eau","qty":15,"unit":"ml","note":"1 c. à soupe d'eau de fleur d'oranger"},{"id":"orange","qty":1,"unit":"piece","note":"zeste fin"},{"id":"pistache","qty":40,"unit":"g","note":"hachées"}],"steps":["Dans une casserole, délayez la fécule dans 200 ml de lait froid jusqu'à ce qu'il n'y ait plus aucun grumeau.","Ajoutez le reste du lait, la crème et le sucre. Portez à feu moyen en fouettant sans arrêt.","Dès les premiers bouillons, baissez le feu et cuisez encore 3 min en fouettant : la crème épaissit nettement et nappe la cuillère.","Hors du feu, ajoutez la fleur d'oranger et la moitié du zeste d'orange. Versez dans 6 coupes.","Laissez refroidir 30 min, puis réfrigérez 3 h minimum. Servez parsemé de pistaches et du reste de zeste."],"tags":["préparation à l’avance","économique","sans gluten","léger"],"seasons":[],"technique":"bouilli","flavors":["lacte","frais","cremeux"],"tips":"Un filet de sirop de miel citronné ou quelques graines de grenade complètent bien."},{"id":"des-clafoutis-quetsches-kefir-sarrasin","name":"Clafoutis aux quetsches, kéfir et sarrasin","description":"Un clafoutis de fin d'été aux quetsches acidulées, dans un appareil au kéfir et à la farine de sarrasin, au goût de noisette et sans gluten.","emoji":"🟣","category":"dessert","mealTypes":["dessert"],"cuisine":"francaise","prepTime":15,"cookTime":40,"difficulty":"tres-facile","servings":6,"ingredients":[{"id":"prune","qty":600,"unit":"g","note":"quetsches ou mirabelles, dénoyautées et coupées en deux"},{"id":"oeuf","qty":4,"unit":"piece"},{"id":"kefir","qty":400,"unit":"ml","note":"de lait entier"},{"id":"farine-sarrasin","qty":70,"unit":"g"},{"id":"sucre","qty":80,"unit":"g","note":"complet"},{"id":"beurre","qty":20,"unit":"g","note":"pour le plat","optional":true},{"id":"cannelle","qty":0.5,"unit":"cac"},{"id":"vanille","qty":1,"unit":"cac","note":"extrait"},{"id":"sel","qty":1,"unit":"pincee"}],"steps":["La veille : préparez la pâte et laissez-la reposer et fermenter une nuit (12 h) à température ambiante, couverte.","Préchauffez le four à 180 °C. Beurrez un plat à gratin en terre de 24 cm et saupoudrez-le d'1 c. à soupe du sucre.","Rangez les demi-quetsches serrées dans le plat, face coupée vers le haut.","Fouettez les œufs avec le reste du sucre, le sel et la cannelle, puis la farine de sarrasin jusqu'à une pâte lisse. Détendez progressivement avec le kéfir et la vanille.","Versez l'appareil sur les fruits et enfournez 35 à 40 min : il doit être gonflé, brun doré sur les bords et pris au centre (une lame ressort propre).","Laissez tiédir 20 min avant de servir : le clafoutis retombe, c'est normal, et le jus des quetsches se fige légèrement."],"tags":["four","familial","économique","sans gluten","fermenté","préparation à l’avance"],"seasons":["ete","automne"],"technique":"four","flavors":["fruite","acidule"],"tips":"En juin, la même base fonctionne avec des cerises noires entières non dénoyautées (comptez 5 min de moins).","restTime":720},{"id":"des-bread-butter-pudding","name":"Bread and butter pudding aux raisins","description":"Le pudding anglais anti-gaspi : tranches de pain au levain rassis beurrées, raisins secs et crème aux œufs muscadée, doré et croustillant dessus.","emoji":"🍞","category":"dessert","mealTypes":["dessert"],"cuisine":"britannique","prepTime":15,"cookTime":40,"restTime":20,"difficulty":"tres-facile","servings":6,"ingredients":[{"id":"pain-levain","qty":300,"unit":"g","note":"rassis, en tranches de 1 cm (ou brioche maison)"},{"id":"beurre","qty":50,"unit":"g","note":"mou"},{"id":"lait","qty":400,"unit":"ml","note":"entier"},{"id":"creme-liquide","qty":200,"unit":"ml"},{"id":"oeuf","qty":4,"unit":"piece"},{"id":"sucre","qty":70,"unit":"g"},{"id":"raisins-secs","qty":60,"unit":"g"},{"id":"muscade","qty":1,"unit":"pincee"},{"id":"vanille","qty":1,"unit":"cac","note":"extrait"},{"id":"confiture","qty":40,"unit":"g","note":"d'abricot, pour lustrer","optional":true}],"steps":["Beurrez un plat à four de 20 × 25 cm. Beurrez les tranches de pain d'un côté et coupez-les en triangles.","Disposez-les en tuiles dans le plat, côté beurré vers le haut, en glissant les raisins secs entre les couches.","Fouettez les œufs avec le sucre, puis ajoutez le lait, la crème, la vanille et la muscade. Versez sur le pain et appuyez avec une spatule pour bien l'imbiber. Laissez reposer 20 min.","Préchauffez le four à 170 °C. Posez le plat dans un plat plus grand rempli de 2 cm d'eau chaude.","Enfournez 35 à 40 min : la crème est prise (elle ne tremble plus au centre) et les pointes de pain sont brunes et croustillantes.","Lustrez éventuellement avec la confiture tiédie et servez chaud ou tiède."],"tags":["four","économique","familial","réconfortant"],"seasons":["automne","hiver"],"technique":"four","flavors":["reconfortant","epice"],"tips":"Idéal pour finir un pain de 3 jours. Se réchauffe 15 min à 160 °C."},{"id":"des-tarte-tatin","name":"Tarte Tatin au caramel et crème crue","description":"Pommes fondantes et confites dans un caramel au beurre, cuites sous une pâte brisée maison et retournées tièdes, servies avec une cuillerée de crème crue.","emoji":"🍎","category":"dessert","mealTypes":["dessert"],"cuisine":"francaise","prepTime":35,"cookTime":60,"restTime":30,"difficulty":"intermediaire","servings":8,"ingredients":[{"id":"pomme","qty":1400,"unit":"g","note":"fermes : reine des reinettes, boskoop ou golden (8 à 9 pommes)"},{"id":"beurre","qty":120,"unit":"g","note":"75 g pâte, 45 g caramel"},{"id":"sucre","qty":140,"unit":"g","note":"120 g caramel, 20 g pâte"},{"id":"farine","qty":160,"unit":"g"},{"id":"eau","qty":50,"unit":"ml","note":"glacée"},{"id":"sel","qty":1,"unit":"pincee"},{"id":"creme-fraiche","qty":200,"unit":"ml","note":"crue, pour servir","optional":true}],"steps":["Pâte : sablez du bout des doigts la farine, 20 g de sucre, le sel et 75 g de beurre froid en dés. Ajoutez l'eau glacée, rassemblez en boule sans pétrir, aplatissez et réfrigérez 30 min.","Épluchez les pommes, coupez-les en quatre et ôtez le cœur.","Dans un moule à manqué de 24 cm allant sur le feu (ou une poêle en fonte), faites fondre 120 g de sucre à feu moyen jusqu'à un caramel blond foncé, 6 à 8 min. Ajoutez 45 g de beurre en dés et mélangez.","Rangez les quartiers de pommes bien serrés, debout sur la tranche, en cercles. Laissez cuire 15 min à feu moyen-doux : le caramel bouillonne et les pommes commencent à se confire.","Préchauffez le four à 190 °C. Étalez la pâte sur 3 mm, posez-la sur les pommes et rentrez les bords à l'intérieur du moule. Piquez de quelques trous.","Enfournez 40 à 45 min, jusqu'à ce que la pâte soit bien dorée et que le jus de caramel bouillonne sur les bords.","Laissez reposer 10 min, puis posez un plat sur le moule et retournez d'un geste franc. Replacez les pommes restées collées. Servez tiède avec la crème crue."],"tags":["four","week-end","familial","réconfortant"],"seasons":["automne","hiver"],"technique":"four","flavors":["sucre","fruite","reconfortant"],"tips":"Choisissez des pommes qui tiennent à la cuisson ; des quartiers trop mûrs se transforment en compote."},{"id":"des-crumble-poires-avoine-noisettes","name":"Crumble poires-gingembre aux flocons d'avoine et noisettes","description":"Poires juteuses relevées de gingembre frais sous un crumble croustillant à l'avoine, aux noisettes et au beurre, peu sucré.","emoji":"🍐","category":"dessert","mealTypes":["dessert"],"cuisine":"britannique","prepTime":20,"cookTime":35,"difficulty":"tres-facile","servings":6,"ingredients":[{"id":"poire","qty":6,"unit":"piece","note":"mûres mais fermes"},{"id":"gingembre","qty":10,"unit":"g","note":"râpé"},{"id":"citron","qty":0.5,"unit":"piece","note":"jus"},{"id":"flocons-avoine","qty":100,"unit":"g"},{"id":"farine","qty":40,"unit":"g"},{"id":"noisette","qty":50,"unit":"g","note":"concassées"},{"id":"beurre","qty":80,"unit":"g","note":"froid, en dés"},{"id":"sucre","qty":60,"unit":"g","note":"complet"},{"id":"cannelle","qty":1,"unit":"cac"},{"id":"sel","qty":1,"unit":"pincee"},{"id":"creme-liquide","qty":150,"unit":"ml","note":"pour servir, ou crème anglaise","optional":true},{"id":"farine-seigle","qty":12,"unit":"g","note":"pour le trempage de l’avoine (phytase)"},{"id":"kefir","qty":12,"unit":"cas","note":"pour le trempage"}],"steps":["La veille au soir : faites tremper les flocons d’avoine 12 h (une nuit) dans de l’eau tiède avec 2 c. à soupe de kéfir ou de yaourt et 1 c. à soupe de farine de seigle (sa phytase dégrade les phytates de l’avoine). Égouttez avant de cuire.","Préchauffez le four à 190 °C.","Pelez les poires, coupez-les en gros cubes de 3 cm et mélangez-les dans un plat à gratin avec le gingembre râpé, le jus de citron, la cannelle et 15 g de sucre.","Dans un saladier, mélangez flocons d'avoine, farine, noisettes, 45 g de sucre et sel. Ajoutez le beurre froid et sablez du bout des doigts jusqu'à obtenir de gros grumeaux irréguliers.","Répartissez le crumble sur les fruits sans tasser.","Enfournez 30 à 35 min : le dessus doit être doré et croustillant, et le jus des poires bouillonner sur les bords.","Laissez tiédir 10 min et servez avec un trait de crème froide."],"tags":["four","familial","réconfortant","économique","préparation à l’avance"],"seasons":["automne","hiver"],"technique":"four","flavors":["fruite","epice","reconfortant"],"tips":"Le crumble cru se congèle : gardez-en un sachet pour un dessert minute sur des pommes ou des prunes.","restTime":720},{"id":"des-pommes-au-four-miel-noix","name":"Pommes au four farcies miel, noix et raisins","description":"Pommes entières rôties jusqu'à éclater, farcies de noix, raisins secs, beurre et miel, servies dans leur jus caramélisé.","emoji":"🍏","category":"dessert","mealTypes":["dessert"],"cuisine":"francaise","prepTime":10,"cookTime":40,"difficulty":"tres-facile","servings":4,"ingredients":[{"id":"pomme","qty":4,"unit":"piece","note":"reinettes ou boskoop"},{"id":"miel","qty":40,"unit":"g"},{"id":"noix","qty":40,"unit":"g","note":"concassées"},{"id":"raisins-secs","qty":30,"unit":"g"},{"id":"beurre","qty":30,"unit":"g"},{"id":"cannelle","qty":0.5,"unit":"cac"},{"id":"creme-fraiche","qty":100,"unit":"ml","note":"épaisse, pour servir","optional":true}],"steps":["Préchauffez le four à 180 °C.","Évidez les pommes avec un vide-pomme sans les percer complètement au fond. Incisez la peau tout autour à mi-hauteur sur 2 mm pour qu'elles n'éclatent pas.","Mélangez noix, raisins secs, cannelle, la moitié du miel et 20 g de beurre mou. Farcissez les pommes en tassant.","Posez-les dans un plat, ajoutez un fond de 3 cas d'eau, déposez le reste du beurre et du miel sur le dessus.","Enfournez 35 à 40 min en arrosant deux fois avec le jus : la chair doit être fondante sous la pointe d'un couteau et la peau plissée.","Servez chaud avec le jus du plat et une cuillerée de crème épaisse."],"tags":["four","économique","réconfortant","sans gluten"],"seasons":["automne","hiver"],"technique":"four","flavors":["fruite","reconfortant","sucre"],"tips":"Variante : farcissez de châtaignes émiettées et d'une cuillère de crème de marrons."},{"id":"des-poires-pochees-vin-epices","name":"Poires pochées au vin rouge et aux épices","description":"Poires entières pochées dans un vin rouge épicé jusqu'à prendre une robe pourpre, servies avec leur sirop réduit et une cuillère de crème.","emoji":"🍷","category":"dessert","mealTypes":["dessert"],"cuisine":"francaise","prepTime":15,"cookTime":45,"restTime":120,"difficulty":"tres-facile","servings":6,"ingredients":[{"id":"poire","qty":6,"unit":"piece","note":"conférence ou williams, fermes"},{"id":"vin-rouge","qty":750,"unit":"ml","note":"côtes-du-rhône ou similaire"},{"id":"sucre","qty":100,"unit":"g"},{"id":"orange","qty":1,"unit":"piece","note":"zeste en rubans + jus"},{"id":"cannelle","qty":1,"unit":"cac","note":"1 bâton"},{"id":"girofle","qty":1,"unit":"pincee","note":"3 clous + 1 étoile de badiane"},{"id":"poivre","qty":1,"unit":"pincee","note":"6 grains"},{"id":"creme-fraiche","qty":150,"unit":"ml","note":"pour servir","optional":true}],"steps":["Dans une casserole juste assez grande pour contenir les poires debout, portez à ébullition le vin, le sucre, les zestes et le jus d'orange, la cannelle, le girofle et le poivre.","Pelez les poires en gardant la queue et coupez une fine tranche à la base pour qu'elles tiennent debout.","Plongez-les dans le vin frémissant (complétez avec un peu d'eau si elles ne sont pas couvertes) et posez un disque de papier cuisson dessus. Pochez à petits frémissements 25 à 35 min en les tournant à mi-cuisson, jusqu'à ce qu'une lame s'y enfonce sans résistance.","Retirez les poires. Faites réduire le sirop à feu vif 10 à 12 min, jusqu'à ce qu'il nappe la cuillère (environ 200 ml restants).","Remettez les poires dans le sirop et laissez-les refroidir dedans, idéalement une nuit au frais pour une couleur bien profonde. Servez avec le sirop et la crème."],"tags":["préparation à l’avance","léger","sans gluten","week-end"],"seasons":["automne","hiver"],"technique":"poche","flavors":["fruite","epice","sucre"],"tips":"Se gardent 4 jours dans leur sirop. L'alcool s'évapore en grande partie pendant la cuisson et la réduction."},{"id":"des-compote-pommes-rhubarbe","name":"Compote pommes-rhubarbe à la vanille","description":"Une compote de printemps acidulée, sucrée au miel, à servir tiède ou froide avec un yaourt entier ou en collation.","emoji":"🌱","category":"dessert","mealTypes":["dessert","collation"],"cuisine":"francaise","prepTime":10,"cookTime":20,"difficulty":"tres-facile","servings":6,"ingredients":[{"id":"rhubarbe","qty":120,"unit":"g","note":"tiges, effilées"},{"id":"pomme","qty":4,"unit":"piece","note":"douces (gala, golden)"},{"id":"miel","qty":60,"unit":"g"},{"id":"vanille","qty":1,"unit":"cac","note":"1 gousse"},{"id":"eau","qty":50,"unit":"ml"},{"id":"yaourt-grec","qty":300,"unit":"g","note":"entier, pour servir","optional":true},{"id":"yaourt-nature","qty":1140,"unit":"g","note":"le calcium limite l’absorption des oxalates"}],"steps":["Effilez la rhubarbe et coupez-la en tronçons de 2 cm. Pelez et coupez les pommes en cubes.","Mettez le tout dans une casserole avec l'eau, le miel et la vanille fendue et grattée.","Couvrez et cuisez 15 min à feu doux en remuant de temps en temps, puis découvrez et poursuivez 5 min pour évaporer le jus : la rhubarbe doit être complètement effondrée et les pommes fondantes.","Écrasez à la fourchette pour une compote rustique ou mixez pour une texture lisse. Goûtez et ajustez avec un peu de miel si la rhubarbe est très acide.","Servez tiède ou froide, avec une cuillerée de yaourt grec.","Servez avec une cuillerée de yaourt nature entier (son calcium limite l’absorption des oxalates)."],"tags":["économique","préparation à l’avance","léger","batch cooking","sans gluten"],"seasons":["printemps"],"technique":"mijote","flavors":["acidule","fruite"],"tips":"Se garde 5 jours au frais, se congèle très bien en portions."},{"id":"des-abricots-rotis-miel-romarin","name":"Abricots rôtis au miel et romarin, ricotta vanillée","description":"Demi-abricots rôtis au beurre et au miel parfumé au romarin, servis chauds sur une ricotta fouettée à la vanille, avec des amandes grillées.","emoji":"🍑","category":"dessert","mealTypes":["dessert"],"cuisine":"francaise","prepTime":10,"cookTime":20,"difficulty":"tres-facile","servings":4,"ingredients":[{"id":"abricot","qty":12,"unit":"piece","note":"mûrs, coupés en deux"},{"id":"miel","qty":40,"unit":"g","note":"de lavande ou toutes fleurs"},{"id":"beurre","qty":30,"unit":"g"},{"id":"romarin","qty":1,"unit":"brin"},{"id":"ricotta","qty":250,"unit":"g"},{"id":"vanille","qty":0.5,"unit":"cac","note":"extrait"},{"id":"amande","qty":40,"unit":"g","note":"effilées"}],"steps":["Préchauffez le four à 200 °C.","Rangez les demi-abricots face coupée vers le haut dans un plat. Faites fondre le beurre avec le miel et les aiguilles de romarin, puis nappez-en les fruits.","Enfournez 15 à 20 min, jusqu'à ce que les abricots soient tendres, légèrement affaissés et caramélisés sur les bords.","Pendant ce temps, faites dorer les amandes 3 min à sec dans une poêle à feu moyen. Fouettez la ricotta avec la vanille 1 min pour l'alléger.","Étalez la ricotta dans les assiettes, posez les abricots chauds dessus et arrosez de leur jus. Parsemez d'amandes."],"tags":["four","léger","sans gluten","économique"],"seasons":["ete"],"technique":"roti","flavors":["fruite","herbace","lacte"],"tips":"Fonctionne aussi avec des pêches ou des prunes coupées en deux (comptez 5 min de plus)."},{"id":"des-gratin-fruits-rouges-sabayon","name":"Gratin de fruits rouges au sabayon","description":"Fraises, framboises et myrtilles nappées d'un sabayon mousseux au vin blanc moelleux, doré quelques instants sous le gril.","emoji":"🍓","category":"dessert","mealTypes":["dessert"],"cuisine":"francaise","prepTime":20,"cookTime":10,"difficulty":"intermediaire","servings":4,"ingredients":[{"id":"fraise","qty":300,"unit":"g"},{"id":"framboise","qty":150,"unit":"g"},{"id":"myrtille","qty":100,"unit":"g"},{"id":"jaune-oeuf","qty":4,"unit":"piece"},{"id":"sucre","qty":60,"unit":"g"},{"id":"vin-blanc","qty":80,"unit":"ml","note":"moelleux : muscat, jurançon ou sauternes"},{"id":"citron","qty":0.5,"unit":"piece","note":"zeste"}],"steps":["Allumez le gril du four. Équeutez et coupez les fraises en deux ; répartissez tous les fruits dans 4 plats à gratin individuels (ou un grand).","Dans un cul-de-poule, mettez les jaunes, le sucre, le vin et le zeste de citron.","Posez le cul-de-poule sur une casserole d'eau frémissante (le fond ne doit pas toucher l'eau) et fouettez sans arrêt 6 à 8 min : le mélange triple de volume, devient pâle et forme un ruban épais qui tient en surface (environ 75 °C).","Nappez aussitôt les fruits de sabayon.","Glissez sous le gril, à 10 cm de la résistance, 1 à 2 min en surveillant : le dessus doit se tacher de doré. Servez immédiatement."],"tags":["léger","week-end","sans gluten","four"],"seasons":["ete"],"technique":"grill","flavors":["fruite","cremeux","acidule"],"tips":"Hors saison : figues et raisins à l'automne, agrumes en hiver."},{"id":"des-cheesecake-basque","name":"Cheesecake basque brûlé","description":"Le gâteau de San Sebastián : sans fond de biscuit, cuit à four très chaud, surface brûlée presque noire et cœur coulant façon crème.","emoji":"🍰","category":"dessert","mealTypes":["dessert"],"cuisine":"espagnole","prepTime":15,"cookTime":35,"restTime":360,"difficulty":"facile","servings":8,"ingredients":[{"id":"mascarpone","qty":400,"unit":"g","note":"ou fromage frais type cream cheese"},{"id":"ricotta","qty":300,"unit":"g","note":"égouttée"},{"id":"creme-liquide","qty":250,"unit":"ml"},{"id":"oeuf","qty":4,"unit":"piece","note":"à température ambiante"},{"id":"sucre","qty":150,"unit":"g"},{"id":"farine","qty":15,"unit":"g"},{"id":"vanille","qty":1,"unit":"cac","note":"extrait"},{"id":"sel","qty":1,"unit":"pincee"}],"steps":["Préchauffez le four à 230 °C (chaleur tournante). Froissez une grande feuille de papier cuisson, mouillez-la, essorez-la et chemisez un moule de 20 cm en laissant dépasser 5 cm au-dessus des bords.","Au fouet, lissez le mascarpone et la ricotta avec le sucre et le sel, 2 min.","Ajoutez les œufs un à un en fouettant entre chaque, puis la vanille et la farine tamisée, puis la crème. Mélangez juste pour lisser, sans incorporer d'air.","Versez dans le moule et enfournez 30 à 35 min : le dessus doit être brun très foncé, presque noir, les bords gonflés et le centre encore très tremblotant (comme une gelée).","Laissez refroidir à température ambiante 2 h (il retombe en se creusant), puis réfrigérez au moins 4 h. Sortez-le 30 min avant de servir pour un cœur crémeux."],"tags":["four","préparation à l’avance","week-end","familial"],"seasons":[],"technique":"four","flavors":["cremeux","lacte","grille"],"tips":"Le cœur doit rester coulant : ne prolongez pas la cuisson même s'il semble liquide au centre."},{"id":"des-ravani-semoule-yaourt-orange","name":"Ravani, gâteau de semoule au yaourt et sirop d'orange","description":"Gâteau grec moelleux à la semoule et au yaourt entier, imbibé à la sortie du four d'un sirop chaud à l'orange et à la cannelle.","emoji":"🍊","category":"dessert","mealTypes":["dessert","collation"],"cuisine":"grecque","prepTime":20,"cookTime":40,"restTime":60,"difficulty":"facile","servings":10,"ingredients":[{"id":"semoule","qty":200,"unit":"g","note":"fine"},{"id":"farine","qty":60,"unit":"g"},{"id":"yaourt-grec","qty":250,"unit":"g","note":"entier"},{"id":"oeuf","qty":4,"unit":"piece"},{"id":"beurre","qty":100,"unit":"g","note":"fondu"},{"id":"sucre","qty":220,"unit":"g","note":"100 g pâte, 120 g sirop"},{"id":"orange","qty":2,"unit":"piece","note":"zeste dans la pâte, jus dans le sirop"},{"id":"eau","qty":200,"unit":"ml","note":"pour le sirop"},{"id":"levure-chimique","qty":2,"unit":"cac"},{"id":"cannelle","qty":1,"unit":"cac","note":"1 bâton pour le sirop"},{"id":"amande","qty":30,"unit":"g","note":"effilées, pour le dessus","optional":true}],"steps":["Sirop : portez à ébullition l'eau, 120 g de sucre, le jus des oranges et le bâton de cannelle ; laissez bouillir 5 min puis refroidissez complètement.","Préchauffez le four à 180 °C. Beurrez un moule carré de 22 cm.","Fouettez les œufs avec 100 g de sucre 3 min jusqu'à ce que le mélange double de volume. Ajoutez le yaourt, le beurre fondu tiède et le zeste d'orange.","Incorporez la semoule, la farine et la levure à la spatule. Versez dans le moule, parsemez d'amandes.","Enfournez 35 à 40 min : le gâteau est bien doré et une pique ressort sèche.","À la sortie du four, piquez la surface et versez lentement le sirop froid sur le gâteau chaud, en 3 fois. Laissez absorber au moins 1 h avant de couper en losanges."],"tags":["four","préparation à l’avance","familial","économique"],"seasons":[],"technique":"four","flavors":["fruite","sucre","lacte"],"tips":"Sirop froid sur gâteau chaud (ou l'inverse), jamais chaud sur chaud : sinon le gâteau devient pâteux. Se garde 4 jours."},{"id":"des-tiramisu-leger-fromage-blanc","name":"Tiramisu léger au fromage blanc et biscuit maison","description":"Un tiramisu plus aérien : crème mascarpone allégée au fromage blanc et aux blancs en neige, sur un biscuit cuillère maison imbibé d'espresso.","emoji":"☕","category":"dessert","mealTypes":["dessert"],"cuisine":"italienne","prepTime":35,"cookTime":10,"restTime":360,"difficulty":"intermediaire","servings":6,"ingredients":[{"id":"mascarpone","qty":250,"unit":"g"},{"id":"fromage-blanc","qty":250,"unit":"g","note":"entier, égoutté"},{"id":"oeuf","qty":5,"unit":"piece","note":"très frais : 3 pour la crème, 2 pour le biscuit"},{"id":"sucre","qty":110,"unit":"g","note":"60 g crème, 50 g biscuit"},{"id":"farine","qty":50,"unit":"g"},{"id":"cafe","qty":250,"unit":"ml","note":"espresso fort, refroidi"},{"id":"cacao","qty":10,"unit":"g"},{"id":"sel","qty":1,"unit":"pincee"}],"steps":["Biscuit : préchauffez le four à 200 °C. Fouettez 2 jaunes avec 25 g de sucre jusqu'à blanchiment. Montez 2 blancs en neige ferme avec 25 g de sucre, incorporez-les délicatement aux jaunes, puis la farine tamisée en soulevant la masse.","Étalez sur une plaque chemisée en un rectangle de 1 cm d'épaisseur. Enfournez 8 à 10 min : le biscuit est doré et souple au toucher. Laissez refroidir et coupez en bandes.","Crème : fouettez 3 jaunes avec 60 g de sucre jusqu'à blanchiment. Ajoutez le mascarpone et le fromage blanc et lissez au fouet.","Montez les 3 blancs restants en neige avec une pincée de sel et incorporez-les à la crème en 3 fois, à la spatule.","Trempez rapidement les bandes de biscuit dans le café (1 s par face) et tapissez-en le fond d'un plat de 20 × 20 cm. Couvrez de la moitié de la crème, recommencez une couche de biscuit et de crème.","Réfrigérez au moins 6 h, idéalement une nuit. Saupoudrez de cacao tamisé juste avant de servir."],"tags":["préparation à l’avance","week-end","léger","familial"],"seasons":[],"technique":"sans-cuisson","flavors":["cremeux","lacte","umami"],"tips":"Les œufs restent crus : utilisez des œufs extra-frais et consommez sous 48 h."},{"id":"des-semifreddo-miel-pistache","name":"Semifreddo au miel et aux pistaches","description":"Parfait glacé italien sans sorbetière : crème fouettée, œufs mousseux au miel et pistaches grillées, tranché comme un gâteau.","emoji":"🍨","category":"dessert","mealTypes":["dessert"],"cuisine":"italienne","prepTime":30,"cookTime":5,"restTime":360,"difficulty":"facile","servings":8,"ingredients":[{"id":"creme-liquide","qty":400,"unit":"ml","note":"entière, très froide"},{"id":"oeuf","qty":4,"unit":"piece","note":"séparés"},{"id":"miel","qty":120,"unit":"g","note":"de châtaignier ou toutes fleurs"},{"id":"pistache","qty":60,"unit":"g","note":"non salées"},{"id":"vanille","qty":1,"unit":"cac","note":"extrait"},{"id":"sel","qty":1,"unit":"pincee"}],"steps":["Torréfiez les pistaches 4 min à sec dans une poêle à feu moyen, puis concassez-les grossièrement. Chemisez un moule à cake de film alimentaire.","Au bain-marie frémissant, fouettez les jaunes avec 80 g de miel 5 min jusqu'à ce que le mélange soit pâle, épais et chaud au doigt (70 °C). Retirez et fouettez encore jusqu'à complet refroidissement.","Montez la crème très froide avec la vanille en chantilly souple.","Montez les blancs avec le sel en neige, ajoutez les 40 g de miel restants et fouettez jusqu'à une meringue brillante.","Incorporez délicatement la chantilly aux jaunes, puis la meringue et les deux tiers des pistaches. Versez dans le moule, lissez et couvrez.","Congelez au moins 6 h. Sortez 10 min avant de servir, démoulez, parsemez du reste des pistaches et tranchez au couteau trempé dans l'eau chaude."],"tags":["préparation à l’avance","week-end","sans gluten","repas froid"],"seasons":["ete"],"technique":"sans-cuisson","flavors":["cremeux","sucre","lacte"],"tips":"Se garde 2 semaines au congélateur, bien filmé."},{"id":"des-yaourt-glace-mangue-citron-vert","name":"Yaourt glacé minute mangue-citron vert","description":"Une glace express mixée en 5 minutes : mangue congelée, yaourt grec entier, miel et citron vert, à la texture de soft-serve.","emoji":"🥭","category":"dessert","mealTypes":["dessert"],"cuisine":"indienne","prepTime":10,"cookTime":0,"difficulty":"tres-facile","servings":4,"ingredients":[{"id":"mangue","qty":400,"unit":"g","note":"en cubes, congelée"},{"id":"yaourt-grec","qty":300,"unit":"g","note":"entier, bien froid"},{"id":"miel","qty":40,"unit":"g"},{"id":"citron-vert","qty":1,"unit":"piece","note":"zeste + jus"},{"id":"cardamome","qty":1,"unit":"pincee","optional":true},{"id":"pistache","qty":20,"unit":"g","note":"concassées","optional":true}],"steps":["Sortez la mangue congelée 5 min avant pour qu'elle se laisse mixer.","Dans un blender puissant ou un robot, mettez mangue, yaourt, miel, zeste et jus de citron vert et la cardamome.","Mixez par impulsions 1 à 2 min en raclant les parois, jusqu'à une texture lisse et épaisse comme une glace italienne.","Servez aussitôt en coupes, parsemé de pistaches. Pour une texture plus ferme, placez 30 min au congélateur."],"tags":["rapide","léger","sans gluten","fermenté"],"seasons":["ete","printemps"],"technique":"mixe","flavors":["fruite","frais","acidule"],"tips":"Pour congeler la mangue : épluchez-la, coupez en cubes et étalez sur une plaque 3 h au congélateur avant de mettre en sachet. Variante pêche-framboise."},{"id":"des-granita-cafe-panna","name":"Granita al caffè con panna","description":"Le granité sicilien au café grattée en cristaux fondants, servi dans un verre avec une chantilly maison peu sucrée.","emoji":"🧊","category":"dessert","mealTypes":["dessert"],"cuisine":"italienne","prepTime":10,"cookTime":0,"restTime":240,"difficulty":"tres-facile","servings":6,"ingredients":[{"id":"cafe","qty":600,"unit":"ml","note":"espresso ou café filtre très fort"},{"id":"sucre","qty":90,"unit":"g","note":"70 g granita, 20 g chantilly"},{"id":"creme-liquide","qty":200,"unit":"ml","note":"entière, très froide"},{"id":"vanille","qty":0.5,"unit":"cac","note":"extrait","optional":true}],"steps":["Dissolvez 70 g de sucre dans le café chaud. Laissez refroidir complètement.","Versez dans un plat métallique ou en verre peu profond (épaisseur de liquide 2 à 3 cm) et placez au congélateur.","Après 1 h, grattez les cristaux formés sur les bords vers le centre avec une fourchette. Recommencez toutes les 30 min pendant 3 h, jusqu'à obtenir une neige de cristaux secs et légers.","Juste avant de servir, fouettez la crème très froide avec 20 g de sucre et la vanille en chantilly souple, 2 min.","Répartissez la granita dans des verres froids et couronnez de chantilly."],"tags":["préparation à l’avance","économique","sans gluten","repas froid"],"seasons":["ete"],"technique":"sans-cuisson","flavors":["frais","cremeux"],"tips":"Se garde 1 semaine au congélateur : regrattez à la fourchette avant de servir."},{"id":"des-fromage-blanc-battu-coulis-fraises","name":"Fromage blanc battu à la crème, coulis de fraises","description":"Le dessert minute de printemps : fromage blanc fermier fouetté avec un peu de crème jusqu'à devenir mousseux, et un coulis de fraises crues au citron.","emoji":"🍓","category":"dessert","mealTypes":["dessert"],"cuisine":"francaise","prepTime":10,"cookTime":0,"difficulty":"tres-facile","servings":4,"ingredients":[{"id":"fromage-blanc","qty":500,"unit":"g","note":"entier, fermier"},{"id":"creme-liquide","qty":100,"unit":"ml","note":"très froide"},{"id":"fraise","qty":300,"unit":"g"},{"id":"miel","qty":30,"unit":"g"},{"id":"citron","qty":0.5,"unit":"piece","note":"jus"},{"id":"menthe","qty":4,"unit":"feuille","optional":true}],"steps":["Mixez 200 g de fraises avec le miel et le jus de citron 30 s, jusqu'à un coulis lisse. Filtrez si vous voulez retirer les grains.","Coupez le reste des fraises en quartiers.","Fouettez le fromage blanc au fouet électrique 1 min, puis ajoutez la crème froide en filet et fouettez encore 2 min, jusqu'à une texture aérienne qui forme des pointes souples.","Répartissez dans des coupes, nappez de coulis, ajoutez les fraises en quartiers et la menthe ciselée."],"tags":["rapide","léger","sans gluten","économique"],"seasons":["printemps","ete"],"technique":"mixe","flavors":["lacte","fruite","frais"],"tips":"Le coulis se garde 2 jours au frais. En hiver, remplacez-le par une compote de coings ou de poires."},{"id":"des-mousse-chocolat-noir","name":"Mousse au chocolat noir à la fleur de sel","description":"Une vraie mousse au chocolat noir, intense et aérienne, juste les œufs, un peu de beurre et 20 g de chocolat par personne.","emoji":"🍫","category":"dessert","mealTypes":["dessert"],"cuisine":"francaise","prepTime":20,"cookTime":5,"restTime":240,"difficulty":"facile","servings":6,"ingredients":[{"id":"chocolat-noir","qty":120,"unit":"g","note":"70 %"},{"id":"oeuf","qty":6,"unit":"piece","note":"très frais, séparés"},{"id":"beurre","qty":20,"unit":"g"},{"id":"sucre","qty":20,"unit":"g"},{"id":"sel","qty":1,"unit":"pincee","note":"fleur de sel"}],"steps":["Faites fondre le chocolat en morceaux avec le beurre au bain-marie à feu doux, en remuant, jusqu'à ce qu'il soit lisse (pas plus de 45 °C). Retirez du feu et laissez tiédir 5 min.","Incorporez les jaunes un à un au fouet : le mélange épaissit et devient brillant.","Montez les blancs en neige avec une pincée de sel. Quand ils forment des pointes souples, ajoutez le sucre et fouettez encore 30 s jusqu'à des pointes fermes et brillantes.","Mélangez énergiquement un quart des blancs au chocolat pour le détendre, puis incorporez le reste en 2 fois à la spatule, en soulevant délicatement la masse, jusqu'à disparition des traces blanches.","Répartissez en 6 petits pots et réfrigérez au moins 4 h. Parsemez de quelques cristaux de fleur de sel au moment de servir."],"tags":["préparation à l’avance","sans gluten","week-end"],"seasons":[],"technique":"sans-cuisson","flavors":["cremeux","sucre"],"tips":"Les œufs sont crus : utilisez des œufs extra-frais et consommez sous 48 h. Garder ce dessert pour les occasions."},{"id":"des-pasteis-de-nata-simplifies","name":"Pastéis de nata simplifiés","description":"Les tartelettes lisboètes revisitées à la maison : pâte feuilletée rapide au beurre, crème à la vanille et au citron, caramélisée à four très chaud.","emoji":"🥧","category":"dessert","mealTypes":["dessert"],"cuisine":"portugaise","prepTime":45,"cookTime":18,"restTime":60,"difficulty":"intermediaire","servings":6,"ingredients":[{"id":"farine","qty":200,"unit":"g"},{"id":"beurre","qty":150,"unit":"g","note":"très froid"},{"id":"eau","qty":90,"unit":"ml","note":"glacée"},{"id":"sel","qty":1,"unit":"pincee"},{"id":"lait","qty":300,"unit":"ml","note":"entier"},{"id":"creme-liquide","qty":100,"unit":"ml"},{"id":"jaune-oeuf","qty":5,"unit":"piece"},{"id":"sucre","qty":120,"unit":"g"},{"id":"fecule-mais","qty":25,"unit":"g"},{"id":"citron","qty":1,"unit":"piece","note":"zeste en ruban"},{"id":"cannelle","qty":1,"unit":"cac","note":"1 bâton + poudre pour servir"}],"steps":["Pâte feuilletée rapide maison : mélangez farine et sel, ajoutez le beurre très froid en cubes de 1 cm sans l'écraser, puis l'eau glacée ; rassemblez grossièrement (il reste des morceaux de beurre visibles). Étalez en rectangle, pliez en trois, tournez d'un quart, recommencez. Réfrigérez 20 min et répétez 2 fois.","Crème : faites frémir le lait et la crème avec le zeste de citron et le bâton de cannelle, infusez 10 min. Fouettez les jaunes, le sucre et la fécule, versez le lait filtré, reversez en casserole et épaississez à feu moyen 2 min en fouettant. Couvrez au contact et laissez tiédir.","Préchauffez le four à 250 °C (le plus chaud possible), sole en position basse.","Étalez la pâte sur 3 mm, roulez-la en boudin serré de 5 cm de diamètre et coupez 12 tronçons de 1,5 cm. Posez chacun à plat dans un moule à muffins beurré et écrasez-le avec le pouce mouillé pour remonter la pâte sur les parois, fine au fond et jusqu'au bord.","Remplissez aux trois quarts de crème tiède.","Enfournez 15 à 18 min, jusqu'à ce que la pâte soit bien dorée et feuilletée et que la crème présente des taches noires caramélisées. Laissez tiédir 10 min et démoulez.","Servez tièdes, saupoudrés de cannelle."],"tags":["four","week-end","familial"],"seasons":[],"technique":"four","flavors":["cremeux","sucre","grille"],"tips":"Sans grille du dessus ? Passez-les 1 à 2 min sous le gril en fin de cuisson pour les taches caramélisées. Comptez 2 tartelettes par portion."},{"id":"des-shortbread-ecossais","name":"Shortbread écossais pur beurre","description":"Biscuits sablés écossais sans œufs, juste du beurre, du sucre et de la farine allégée de farine de riz, cuits lentement pour rester pâles et friables.","emoji":"🍪","category":"dessert","mealTypes":["dessert","collation"],"cuisine":"britannique","prepTime":15,"cookTime":35,"difficulty":"tres-facile","servings":8,"ingredients":[{"id":"farine","qty":200,"unit":"g"},{"id":"farine-riz","qty":50,"unit":"g","note":"ou fécule"},{"id":"beurre","qty":170,"unit":"g","note":"doux, mou"},{"id":"sucre","qty":70,"unit":"g","note":"fin"},{"id":"sel","qty":1,"unit":"pincee"}],"steps":["Préchauffez le four à 160 °C. Chemisez un moule carré de 20 cm de papier cuisson.","Crémez le beurre mou avec le sucre et le sel à la spatule 2 min, jusqu'à ce qu'il soit lisse et pâle.","Ajoutez la farine et la farine de riz tamisées et mélangez du bout des doigts jusqu'à une pâte sableuse qui se tient quand on la presse.","Tassez la pâte uniformément dans le moule (1,5 cm d'épaisseur), lissez au dos d'une cuillère, prédécoupez 16 bâtonnets à la lame et piquez à la fourchette.","Enfournez 30 à 35 min : le shortbread doit rester pâle, juste blond sur les bords, et ferme au toucher au centre.","Saupoudrez d'1 c. à café de sucre à la sortie du four, recoupez les bâtonnets aussitôt et laissez refroidir complètement dans le moule (ils durcissent en refroidissant)."],"tags":["four","préparation à l’avance","économique","familial"],"seasons":[],"technique":"four","flavors":["lacte","sucre"],"tips":"Se garde 10 jours en boîte métallique. Comptez 2 bâtonnets par portion, avec un thé ou des fruits pochés."},{"id":"des-crepes-suzette","name":"Crêpes Suzette à l'orange","description":"Crêpes fines pliées en quatre et réchauffées dans un caramel au beurre et au jus d'orange frais, zestes confits compris.","emoji":"🍊","category":"dessert","mealTypes":["dessert"],"cuisine":"francaise","prepTime":20,"cookTime":25,"restTime":30,"difficulty":"intermediaire","servings":4,"ingredients":[{"id":"farine","qty":125,"unit":"g"},{"id":"oeuf","qty":2,"unit":"piece"},{"id":"lait","qty":300,"unit":"ml","note":"entier"},{"id":"beurre","qty":70,"unit":"g","note":"20 g pâte, 50 g sauce"},{"id":"sucre","qty":60,"unit":"g","note":"10 g pâte, 50 g sauce"},{"id":"orange","qty":3,"unit":"piece","note":"non traitées : zeste de 2, jus de 3"},{"id":"sel","qty":1,"unit":"pincee"}],"steps":["Pâte : mélangez farine, 10 g de sucre et sel, creusez un puits, ajoutez les œufs et fouettez en versant le lait petit à petit jusqu'à une pâte lisse et fluide. Ajoutez 20 g de beurre fondu. Laissez reposer 30 min.","Cuisez 8 crêpes fines dans une poêle de 24 cm légèrement beurrée à feu moyen-vif, 1 min par face : elles doivent être dorées et dentelées. Pliez-les en quatre.","Sauce : dans une grande poêle, faites fondre 50 g de sucre à feu moyen jusqu'à un caramel blond, 4 min.","Ajoutez le zeste et le jus des oranges (attention aux projections), laissez le caramel se dissoudre en remuant, puis ajoutez 50 g de beurre et faites bouillonner 3 à 4 min jusqu'à une sauce sirupeuse.","Glissez les crêpes pliées dans la sauce, arrosez-les 2 min à feu doux pour qu'elles s'imbibent. Servez aussitôt, 2 crêpes par personne, nappées de sauce."],"tags":["week-end","familial","une poêle"],"seasons":["hiver"],"technique":"poele","flavors":["fruite","sucre"],"tips":"Pour flamber, ajoutez 3 c. à soupe de Grand Marnier dans la sauce juste avant de servir."},{"id":"des-crema-catalana","name":"Crema catalana au citron et à la cannelle","description":"La crème catalane infusée au zeste de citron et à la cannelle, cuite sur le feu puis recouverte d'une croûte de sucre brûlée au dernier moment.","emoji":"🔥","category":"dessert","mealTypes":["dessert"],"cuisine":"espagnole","prepTime":15,"cookTime":15,"restTime":180,"difficulty":"facile","servings":6,"ingredients":[{"id":"lait","qty":750,"unit":"ml","note":"entier"},{"id":"jaune-oeuf","qty":6,"unit":"piece"},{"id":"sucre","qty":150,"unit":"g","note":"90 g crème, 60 g pour brûler"},{"id":"fecule-mais","qty":25,"unit":"g"},{"id":"citron","qty":1,"unit":"piece","note":"zeste en rubans"},{"id":"cannelle","qty":1,"unit":"cac","note":"1 bâton"}],"steps":["Faites chauffer 650 ml de lait avec les zestes de citron et le bâton de cannelle jusqu'à frémissement ; couvrez et laissez infuser 15 min hors du feu.","Fouettez les jaunes avec 90 g de sucre, puis délayez la fécule avec les 100 ml de lait froid restants et ajoutez-la.","Filtrez le lait infusé sur ce mélange en fouettant, reversez dans la casserole et cuisez à feu doux en remuant sans arrêt avec une cuillère en bois, 6 à 8 min, jusqu'à ce que la crème nappe épaissement la cuillère et laisse un sillon net. Ne la laissez pas bouillir.","Versez dans 6 cassolettes plates en terre, laissez refroidir puis réfrigérez au moins 3 h.","Juste avant de servir, saupoudrez chaque crème de 10 g de sucre en couche fine et caramélisez au chalumeau ou au fer à brûler jusqu'à une croûte ambre foncé et craquante."],"tags":["préparation à l’avance","sans gluten","familial","économique"],"seasons":[],"technique":"bouilli","flavors":["acidule","grille","cremeux"],"tips":"La crème se prépare la veille ; on ne brûle le sucre qu'au moment de servir pour garder le craquant."},{"id":"des-mont-blanc-verrine","name":"Mont-blanc en verrine, chantilly mascarpone","description":"Le mont-blanc sans pâtisserie : crème de marrons, chantilly légère au mascarpone et vermicelles de purée de châtaigne, à monter en 10 minutes.","emoji":"🌰","category":"dessert","mealTypes":["dessert"],"cuisine":"francaise","prepTime":20,"cookTime":5,"restTime":60,"difficulty":"tres-facile","servings":4,"ingredients":[{"id":"chataigne","qty":200,"unit":"g","note":"cuites, sous vide ou bocal"},{"id":"lait","qty":60,"unit":"ml","note":"entier"},{"id":"creme-marrons","qty":200,"unit":"g"},{"id":"creme-liquide","qty":200,"unit":"ml","note":"entière, très froide"},{"id":"mascarpone","qty":100,"unit":"g"},{"id":"sucre","qty":15,"unit":"g"},{"id":"vanille","qty":1,"unit":"cac","note":"extrait"},{"id":"cacao","qty":4,"unit":"g","note":"pour saupoudrer","optional":true}],"steps":["Chauffez les châtaignes avec le lait 5 min à feu doux, puis mixez finement jusqu'à une purée épaisse et lisse, qui se tient. Laissez refroidir.","Fouettez la crème très froide avec le mascarpone, le sucre et la vanille 2 à 3 min jusqu'à une chantilly ferme qui tient au fouet.","Répartissez la crème de marrons au fond de 4 verrines, puis une généreuse couche de chantilly.","Passez la purée de châtaigne au presse-purée, au presse-ail ou dans une poche à douille fine pour former des vermicelles en dôme sur la chantilly.","Réfrigérez au moins 1 h. Saupoudrez d'un voile de cacao au moment de servir."],"tags":["préparation à l’avance","sans gluten","réconfortant","week-end"],"seasons":["automne","hiver"],"technique":"sans-cuisson","flavors":["cremeux","reconfortant","sucre"],"tips":"Version de fête : posez une petite meringue maison au fond de chaque verrine, elle apporte le craquant d'origine."},{"id":"des-rodgrod-med-flode","name":"Rødgrød med fløde, compote danoise de fruits rouges","description":"La « gruau rouge » danoise : fruits rouges d'été cuits brièvement et liés à la fécule, servis froids avec un filet de crème entière.","emoji":"🫐","category":"dessert","mealTypes":["dessert"],"cuisine":"nordique","prepTime":10,"cookTime":10,"restTime":120,"difficulty":"tres-facile","servings":6,"ingredients":[{"id":"framboise","qty":300,"unit":"g"},{"id":"fraise","qty":300,"unit":"g"},{"id":"myrtille","qty":200,"unit":"g","note":"cassis ou groseilles idéalement"},{"id":"sucre","qty":90,"unit":"g"},{"id":"eau","qty":300,"unit":"ml"},{"id":"fecule-mais","qty":30,"unit":"g","note":"ou fécule de pomme de terre"},{"id":"creme-liquide","qty":200,"unit":"ml","note":"entière, froide"}],"steps":["Équeutez les fraises et coupez-les en deux. Égrappez les groseilles ou cassis.","Dans une casserole, portez à frémissement 250 ml d'eau avec le sucre. Ajoutez tous les fruits et cuisez 4 à 5 min à feu moyen, juste jusqu'à ce qu'ils éclatent et rendent leur jus.","Délayez la fécule dans les 50 ml d'eau froide restants. Versez dans les fruits en remuant et laissez épaissir 1 min à frémissement : la compote devient brillante et nappante (ne la faites pas bouillir longtemps, elle deviendrait gluante).","Versez dans des coupes, saupoudrez d'un voile de sucre pour éviter la peau, laissez refroidir puis réfrigérez 2 h.","Servez froid, avec la crème froide versée en filet à la table."],"tags":["économique","préparation à l’avance","léger","sans gluten"],"seasons":["ete"],"technique":"bouilli","flavors":["fruite","acidule","lacte"],"tips":"Se garde 3 jours au frais. Délicieux aussi au petit-déjeuner sur un skyr."},{"id":"des-figues-roties-yaourt-miel-thym","name":"Figues rôties au miel de thym, yaourt grec et noix","description":"Figues fraîches fendues et rôties sous le gril au miel de thym, servies sur un yaourt grec épais avec des noix croquantes.","emoji":"🍯","category":"dessert","mealTypes":["dessert"],"cuisine":"grecque","prepTime":5,"cookTime":10,"difficulty":"tres-facile","servings":4,"ingredients":[{"id":"figue","qty":8,"unit":"piece","note":"mûres"},{"id":"miel","qty":40,"unit":"g","note":"de thym"},{"id":"yaourt-grec","qty":400,"unit":"g","note":"entier"},{"id":"noix","qty":40,"unit":"g","note":"cerneaux"},{"id":"thym","qty":2,"unit":"brin"},{"id":"cannelle","qty":1,"unit":"pincee"}],"steps":["Allumez le gril du four. Fendez les figues en croix aux trois quarts de leur hauteur et écartez légèrement.","Posez-les dans un petit plat, arrosez de la moitié du miel, parsemez de feuilles de thym et de cannelle.","Glissez sous le gril à 10 cm de la résistance, 6 à 8 min, jusqu'à ce que les figues soient chaudes, juteuses et caramélisées sur les bords. Ajoutez les noix dans le plat pour les 2 dernières minutes.","Étalez le yaourt dans les assiettes, posez les figues chaudes dessus, arrosez du jus du plat et du reste de miel."],"tags":["rapide","léger","sans gluten","économique"],"seasons":["ete","automne"],"technique":"grill","flavors":["fruite","lacte","herbace"],"tips":"Avec une feta émiettée à la place du yaourt, c'est aussi un très bon apéritif sucré-salé."},{"id":"des-ayva-tatlisi-coings-kaymak","name":"Ayva tatlısı, coings pochés au sirop et crème épaisse","description":"Demi-coings pochés lentement dans un sirop qui leur donne une couleur rubis, servis froids avec une crème épaisse façon kaymak et des pistaches.","emoji":"🍐","category":"dessert","mealTypes":["dessert"],"cuisine":"turque","prepTime":15,"cookTime":60,"restTime":120,"difficulty":"facile","servings":4,"ingredients":[{"id":"coing","qty":2,"unit":"piece","note":"gros, coupés en deux"},{"id":"sucre","qty":120,"unit":"g"},{"id":"eau","qty":400,"unit":"ml"},{"id":"citron","qty":0.5,"unit":"piece","note":"jus"},{"id":"girofle","qty":1,"unit":"pincee","note":"4 clous"},{"id":"cannelle","qty":1,"unit":"cac","note":"1 bâton","optional":true},{"id":"creme-fraiche","qty":150,"unit":"ml","note":"épaisse, façon kaymak"},{"id":"pistache","qty":20,"unit":"g","note":"moulues"}],"steps":["Lavez et brossez les coings. Coupez-les en deux dans la hauteur, évidez le cœur à la cuillère parisienne en gardant pépins et cœurs.","Dans une sauteuse large, posez les pépins et cœurs au fond (ils donneront la couleur rouge et la texture du sirop), puis les demi-coings, face coupée vers le haut. Saupoudrez du sucre, ajoutez l'eau, le jus de citron, le girofle et la cannelle.","Portez à frémissement, couvrez et pochez à feu doux 50 à 60 min en arrosant les fruits de sirop toutes les 15 min, jusqu'à ce qu'ils soient tendres, translucides et rose ambré.","Retirez le couvercle les 10 dernières minutes pour réduire le sirop jusqu'à ce qu'il soit nappant.","Laissez refroidir dans le sirop puis réfrigérez 2 h. Servez chaque demi-coing arrosé de sirop, avec une quenelle de crème épaisse et des pistaches."],"tags":["préparation à l’avance","sans gluten","week-end"],"seasons":["automne","hiver"],"technique":"poche","flavors":["fruite","sucre","lacte"],"tips":"Se garde 4 jours dans son sirop au frais."},{"id":"des-shiratama-dango-mitarashi","name":"Shiratama dango, sauce mitarashi","description":"Petites boules moelleuses de farine de riz gluant, pochées puis dorées, nappées d'une sauce sucrée-salée au soja : le goûter des fêtes japonaises.","emoji":"🍡","category":"dessert","mealTypes":["dessert","collation"],"cuisine":"japonaise","prepTime":15,"cookTime":10,"difficulty":"facile","servings":4,"ingredients":[{"id":"farine-riz","qty":150,"unit":"g","note":"farine de riz gluant (shiratamako ou mochiko)"},{"id":"eau","qty":230,"unit":"ml","note":"130 ml pâte, 100 ml sauce"},{"id":"sucre","qty":50,"unit":"g"},{"id":"sauce-soja","qty":30,"unit":"ml"},{"id":"fecule-mais","qty":8,"unit":"g","note":"ou fécule de pomme de terre"},{"id":"mirin","qty":15,"unit":"ml","optional":true}],"steps":["Dans un saladier, versez l'eau (130 ml) petit à petit sur la farine de riz en malaxant à la main, jusqu'à une pâte lisse, souple et douce comme un lobe d'oreille.","Formez des boules de 2,5 cm (environ 20). Creusez légèrement le centre avec le pouce pour une cuisson homogène.","Plongez-les dans une grande casserole d'eau bouillante. Quand elles remontent à la surface (2 à 3 min), laissez encore 1 min, puis transférez-les dans un bol d'eau glacée.","Sauce mitarashi : dans une petite casserole, mélangez à froid sucre, sauce soja, mirin, 100 ml d'eau et fécule. Portez à frémissement en remuant sans cesse, 1 à 2 min, jusqu'à une sauce translucide et sirupeuse.","Égouttez les dango, enfilez-en 3 à 4 sur des piques. Faites-les dorer 1 à 2 min par face dans une poêle chaude à sec (ou au chalumeau) jusqu'à des marques grillées.","Nappez généreusement de sauce tiède et servez aussitôt."],"tags":["sans gluten","économique","familial"],"seasons":[],"technique":"bouilli","flavors":["umami","sucre","grille"],"tips":"Les dango durcissent au réfrigérateur : préparez-les le jour même. Variante : servez-les nature avec des fraises et un sirop de sucre complet."}]`);export{e as default};